import mongoose from "mongoose"

const studentSchema = new mongoose.Schema(
  {
    // Admission number is generated by the backend.
    admissionNo: {
      type: String,
      required: [true, "Admission number is required"],
      unique: true,
      trim: true,
    },
    firstName: {
      type: String,
      required: [true, "First name is required"],
      trim: true,
      minlength: [2, "First name must contain at least 2 characters"],
      maxlength: [50, "First name cannot exceed 50 characters"],
      match: [/^[A-Z]/, "First name must start with an uppercase letter"],
    },
    // Student's last name is optional.
    // If supplied, it must satisfy the frontend's name rules.
    lastName: {
      type: String,
      default: "",
      trim: true,
      validate: {
        validator(value) {
          if (value === undefined || value === "") {
            return true
          }

          return (
            typeof value === "string" &&
            value.length >= 2 &&
            value.length <= 50 &&
            /^[A-Z]/.test(value)
          )
        },
        message:
          "Last name must be empty or contain 2-50 characters and start with an uppercase letter",
      },
    },
    // Student's gender.
    gender: {
      type: String,
      enum: {
        values: ["Male", "Female", "Other"],
        message: "Invalid student gender",
      },
      required: [true, "Gender is required"],
    },
    // Date of birth is stored as YYYY-MM-DD.
    dob: {
      type: String,
      required: [true, "Date of birth is required"],
      trim: true,
      match: [
        /^\d{4}-\d{2}-\d{2}$/,
        "Date of birth must use YYYY-MM-DD format",
      ],
      validate: {
        validator(value) {
          if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) {
            return true
          }

          const date = value

          // Validate that the date is a real calendar date
          const [year, month, day] = date.split("-").map(Number)
          const parsedDate = new Date(year, month - 1, day)

          if (
            parsedDate.getFullYear() !== year ||
            parsedDate.getMonth() !== month - 1 ||
            parsedDate.getDate() !== day
          ) {
            return false
          }

          // Validate that date is not in the future
          const today = new Date().toISOString().slice(0, 10)

          if (date > today) {
            return false
          }

          return true
        },
        message:
          "Date of birth must be a valid calendar date and cannot be in the future",
      },
    },
    // Student's nationality.
    nationality: {
      type: String,
      default: "Indian",
      required: [true, "Nationality is required"],
      trim: true,
      match: [/^[A-Z]/, "Nationality must start with an uppercase letter"],
    },

    // Supported curriculum.
    curriculum: {
      type: String,
      enum: {
        values: ["CBSE"],
        message: "Invalid curriculum",
      },
      required: [true, "Curriculum is required"],
    },

    // Medical information is optional.
    allergies: {
      type: String,
      default: "",
      trim: true,
      maxlength: [100, "Allergies cannot exceed 100 characters"],
    },

    medicalNotes: {
      type: String,
      default: "",
      trim: true,
      maxlength: [500, "Medical notes cannot exceed 500 characters"],
    },

    // Languages spoken by the student.
    languages: {
      type: String,
      default: "",
      required: [true, "Languages are required"],
      trim: true,
      maxlength: [100, "Languages cannot exceed 100 characters"],
      match: [/^[A-Z]/, "Languages must start with an uppercase letter"],
    },

    // Reference to the student's class.
    classId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Class",
      required: [true, "Class ID is required"],
    },

    // Generated by the backend.
    rollNo: {
      type: String,
      required: [true, "Roll number is required"],
      trim: true,
      match: [/^\d+$/, "Roll number must contain digits only"],
    },

    // Admission date is stored as YYYY-MM-DD.
    admissionDate: {
      type: String,
      required: [true, "Admission date is required"],
      trim: true,
      match: [
        /^\d{4}-\d{2}-\d{2}$/,
        "Admission date must use YYYY-MM-DD format",
      ],
      validate: {
        validator(value) {
          if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) {
            return true
          }

          const date = value

          // Validate that the date is a real calendar date
          const [year, month, day] = date.split("-").map(Number)
          const parsedDate = new Date(year, month - 1, day)

          if (
            parsedDate.getFullYear() !== year ||
            parsedDate.getMonth() !== month - 1 ||
            parsedDate.getDate() !== day
          ) {
            return false
          }

          // Validate that date is not in the future
          const today = new Date().toISOString().slice(0, 10)

          if (date > today) {
            return false
          }

          return true
        },
        message:
          "Admission date must be a valid calendar date and cannot be in the future",
      },
    },

    // Transport information.
    transportRequired: {
      type: String,
      enum: {
        values: ["yes", "no"],
        message: "Transport required must be yes or no",
      },
      default: "no",
      required: [true, "Transport selection is required"],
    },

    transportRoute: {
      type: String,
      default: "",
      trim: true,
      maxlength: [100, "Transport route cannot exceed 100 characters"],
      required: [
        function () {
          return this.transportRequired === "yes"
        },
        "Transport route is required when transport is enabled",
      ],
    },

    // References to linked parents.
    parentIds: {
      type: [
        {
          type: mongoose.Schema.Types.ObjectId,
          ref: "Parent",
        },
      ],
      default: [],
    },

    // Academic year must use YYYY-YYYY format.
    academicYear: {
      type: String,
      required: [true, "Academic year is required"],
      trim: true,
      match: [/^\d{4}-\d{4}$/, "Academic year must use YYYY-YYYY format"],
      validate: {
        validator(value) {
          if (!/^\d{4}-\d{4}$/.test(value)) {
            return true
          }

          const [startYear, endYear] = value.split("-").map(Number)

          return endYear === startYear + 1
        },
        message: "The ending year must be one year after the starting year",
      },
    },

    // Student status.
    status: {
      type: String,
      enum: {
        values: [
          "active",
          "inactive",
          "transferred",
          "passed-out",
          "suspended",
        ],
        message: "Invalid student status",
      },
      default: "active",
      required: [true, "Student status is required"],
    },

    // Student's address.
    address: {
      type: String,
      required: [true, "Address is required"],
      trim: true,
      maxlength: [300, "Address cannot exceed 300 characters"],
    },
  },
  {
    timestamps: true,
  },
)

// Supports class-based student filtering.
studentSchema.index({ classId: 1 })

// Supports queries filtering students by status.
studentSchema.index({ status: 1 })

export const Student = mongoose.model("Student", studentSchema, "students")

